mapper.select:
select sum(`actual_duration`)
from `att_approve_log`
where `business_type` = 'OVERTIME'
  and `status` in ("PROGRESS", "FINISHED")
  and `user_id` = #{userId}
  and `start_time` >= #{startTime}
  and `end_time` <= #{endTime}

select b.`user_id`,b.`user_name`, b.`org_id`,count(1) num
from `att_approve_log` a
inner join `att_clock_in_records` b on a.`clock_in_id` = b.`id`
where a.`business_type` = 'REPAIR_CLOCK'
and a.`status` = 'FINISHED'
and a.`start_time` >= #{param.period.begin}
and a.`end_time` <= #{param.period.end}

    and b.`user_name`=#{param.userName}


    and b.`org_id`=#{param.orgId}

GROUP BY a.`user_id`

select b.user_id,b.user_name, b.org_id, c.group_name, count(1) num
from `att_approve_log` a
inner join `att_clock_in_records` b on a.`clock_in_id` = b.`id`
where a.`business_type` = 'REPAIR_CLOCK'
and a.`status` = 'FINISHED'
and a.`start_time` >= #{param.period.begin}
and a.`end_time` <= #{param.period.end}

    and b.`user_name`=#{param.userName}

GROUP BY a.`user_id`

select b.`user_id`,b.`user_name`, b.`org_id`, count(1) num
from `att_approve_log` a
inner join `att_clock_in_records` b on a.`clock_in_id` = b.`id`
where a.`business_type` = 'REPAIR_CLOCK'
and a.`status` = 'FINISHED'
and a.`start_time` >= #{param.period.begin}
and a.`end_time` <= #{param.period.end}

    and b.`user_name`=#{param.userName}

GROUP BY a.`user_id`

select b.`user_id`,b.`user_name`, b.`org_id`, c.`group_name`, count(1) num
from `att_approve_log` a
inner join `att_clock_in_records` b on a.`clock_in_id` = b.`id`
inner join `att_group_staff` c on b.`user_id` = c.`staff_id`
where a.`business_type` = 'REPAIR_CLOCK'
and a.`status` = 'FINISHED'
and a.`start_time` >= #{param.period.begin}
and a.`end_time` <= #{param.period.end}
and c.`group_id`=#{param.groupId}

    and b.`user_name`=#{param.userName}

GROUP BY a.`user_id`
